"""Exact piecewise-linear gap events in an attached Bundle's common interior.

This is an opt-in construction primitive, not a finished pavement surface.
The four original offset wires may have independent terminal planes. Only
their common axis interval is queried; none of their physical points moves.
Every boundary knot is retained in the event calculation, so a short overlap
cannot be missed by a regular sampling grid. Nonmonotone or contained-member
configurations are reported outside this initial branch's supported domain.
"""
import bpy
from .path_surface_nodes import _Nodes
from . import boundary_quad_bridge_nodes as bridge
from . import curved_separator_surface_nodes as surface

NAME = 'Prochitecture Streets / Attached Bundle interior gap events v1'
MAX_KNOTS = 16384
SIDES = ('Side A', 'Inner A', 'Inner B', 'Side B')


def _line(g, count):
    node = g.node('GeometryNodeMeshLine', 'Materialize ordered event records')
    g.set(count, node.inputs['Count'])
    return node.outputs['Mesh']


def _select(g, geometry, selection):
    node = g.node('GeometryNodeSeparateGeometry', 'Select exact metric records')
    node.domain = 'POINT'
    g.set(geometry, node.inputs['Geometry']); g.set(selection, node.inputs['Selection'])
    return node.outputs['Selection']


def _unique(g, geometry):
    """Remove only exactly equal scalar coordinates, without a spatial weld."""
    index = g.node('GeometryNodeInputIndex', 'Sorted metric record').outputs[0]
    metric = g.named('st_bu_metric', 'FLOAT')
    sort = g.node('GeometryNodeSortElements', 'Sort every original boundary knot')
    sort.domain = 'POINT'
    g.set(geometry, sort.inputs['Geometry']); g.set(metric, sort.inputs['Sort Weight'])
    previous = g.sample(sort.outputs['Geometry'], metric,
        g.math('MAXIMUM', 0., g.math('SUBTRACT', index, 1.)), 'FLOAT')
    return _select(g, sort.outputs['Geometry'], g.either(g.compare(index, 0, kind='INT'),
        g.compare(metric, previous, 'GREATER_THAN')))


def build():
    if NAME in bpy.data.node_groups: return bpy.data.node_groups[NAME]
    tree = bpy.data.node_groups.new(NAME, 'GeometryNodeTree'); g = _Nodes(tree)
    for name in (*SIDES, 'Head'):
        tree.interface.new_socket(name=name, in_out='INPUT', socket_type='NodeSocketGeometry')
    for name, kind in (('Stations', 'NodeSocketGeometry'), ('Events', 'NodeSocketGeometry'),
                       ('Diagnostics', 'NodeSocketGeometry'), ('Valid', 'NodeSocketBool'),
                       ('Origin', 'NodeSocketVector'), ('Axis', 'NodeSocketVector'),
                       ('Lateral', 'NodeSocketVector')):
        tree.interface.new_socket(name=name, in_out='OUTPUT', socket_type=kind)
    inp = g.node('NodeGroupInput', 'Original four curb chains and head identities')
    out = g.node('NodeGroupOutput', 'Common-interior events; independent end caps remain separate')
    pos = g.node('GeometryNodeInputPosition', 'Unchanged physical boundary position').outputs[0]
    index = g.node('GeometryNodeInputIndex', 'Current metric rank').outputs[0]
    endpoints = []; checks = []
    for name in ('Side A', 'Side B'):
        first, found = surface._head_identity(g, inp.outputs[name], inp.outputs['Head'])
        ordered, count, _, _, valid, _ = surface._chain(g, inp.outputs[name], first, 0)
        endpoints.append((g.sample(ordered, pos, 0, 'FLOAT_VECTOR'),
            g.sample(ordered, pos, g.math('SUBTRACT', count, 1.), 'FLOAT_VECTOR')))
        checks.extend((found, valid))
    origin = bridge._mix(g, endpoints[0][0], endpoints[1][0])
    tail = bridge._mix(g, endpoints[0][1], endpoints[1][1])
    chord = g.vector('SUBTRACT', tail, origin)
    chord = g.xyz(g.component(chord, 'X'), g.component(chord, 'Y'))
    axis = g.vector('NORMALIZE', chord)
    right = g.right(axis)
    orientation = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', endpoints[1][0], endpoints[0][0]), right)
    lateral = g.vector('SCALE', right, g.switch(g.compare(orientation, 0., 'LESS_THAN'), 1., -1.))
    checks.append(g.compare(g.vector('LENGTH', chord), 1e-5, 'GREATER_THAN'))
    wires = [bridge._wire(g, inp.outputs[name], axis, at, origin, shared=True)
             for at, name in enumerate(SIDES)]
    lo, hi = wires[0][2:4]
    for wire in wires[1:]:
        lo = g.math('MAXIMUM', lo, wire[2]); hi = g.math('MINIMUM', hi, wire[3])
    checks.extend(w[4] for w in wires)
    checks.append(g.compare(g.math('SUBTRACT', hi, lo), 1e-5, 'GREATER_THAN'))
    metric = g.named('st_bu_metric', 'FLOAT')
    parts = [g.store(w[0], 'st_bu_metric', g.named('_bridge_metric', 'FLOAT')) for w in wires]
    ends = g.store(_line(g, 2), 'st_bu_metric', g.switch(g.compare(index, 0, kind='INT'), hi, lo))
    mandatory = _unique(g, bridge._join(g, *parts, ends))
    mandatory = _select(g, mandatory, g.all(g.compare(metric, lo, 'GREATER_EQUAL'),
        g.compare(metric, hi, 'LESS_EQUAL')))

    def query(s):
        return [wire[5](s) for wire in wires]

    def gap(values):
        # Subtract the two physical points before projecting. This avoids
        # subtracting large independent global transverse coordinates.
        return g.vector('DOT_PRODUCT', g.vector('SUBTRACT', values[2], values[1]), lateral)

    count = bridge._size(g, mandatory)
    checks.append(g.compare(count, MAX_KNOTS, 'LESS_EQUAL', 'INT'))
    s0 = g.sample(mandatory, metric, index, 'FLOAT')
    s1 = g.sample(mandatory, metric, g.math('ADD', index, 1.), 'FLOAT')
    f0, f1 = gap(query(s0)), gap(query(s1))
    crosses = g.either(g.all(g.compare(f0, 0., 'LESS_THAN'), g.compare(f1, 0., 'GREATER_THAN')),
                      g.all(g.compare(f1, 0., 'LESS_THAN'), g.compare(f0, 0., 'GREATER_THAN')))
    alpha = g.math('DIVIDE', f0, g.math('SUBTRACT', f0, f1))
    root = g.math('ADD', s0, g.math('MULTIPLY', alpha, g.math('SUBTRACT', s1, s0)))
    roots = g.store(_line(g, g.math('MAXIMUM', 2., g.math('SUBTRACT', count, 1.))), 'st_bu_metric', root)
    roots = _select(g, roots, g.all(crosses, g.compare(index, g.math('SUBTRACT', count, 1.), 'LESS_THAN')))
    roots = g.store(roots, 'st_bu_event', 1, 'INT')
    # Exact knot contact is a separate event. Default float-comparison epsilon
    # must not turn a merely narrow gap into a second displaced contact.
    knot_gap = gap(query(metric))
    zero = g.compare(g.math('ABSOLUTE', knot_gap), 0., 'LESS_EQUAL')
    previous_gap = g.sample(mandatory, knot_gap, g.math('MAXIMUM', 0., g.math('SUBTRACT', index, 1.)), 'FLOAT')
    following_gap = g.sample(mandatory, knot_gap,
        g.math('MINIMUM', g.math('SUBTRACT', count, 1.), g.math('ADD', index, 1.)), 'FLOAT')
    endpoint = g.either(g.compare(index, 0, kind='INT'), g.compare(index, g.math('SUBTRACT', count, 1.), kind='INT'))
    contact_end = g.either(endpoint, g.either(g.compare(g.math('ABSOLUTE', previous_gap), 0., 'GREATER_THAN'),
        g.compare(g.math('ABSOLUTE', following_gap), 0., 'GREATER_THAN')))
    touches = g.store(_select(g, mandatory, g.all(zero, contact_end)), 'st_bu_event', 2, 'INT')
    events = bridge._join(g, roots, touches)
    all_knots = _unique(g, bridge._join(g, mandatory, events))
    n = bridge._size(g, all_knots)
    table = g.store(_line(g, n), 'st_bu_metric', g.sample(all_knots, metric, index, 'FLOAT'))
    values = query(metric)
    for name, value in zip(('outer_a', 'inner_a', 'inner_b', 'outer_b'), values):
        table = g.store(table, 'st_bu_'+name, value, 'FLOAT_VECTOR')
    table = g.store(table, 'st_bu_gap', gap(values))
    # Strictly ordered shoulders and no containment prove the limited chart
    # remains a whole-width strip, even while the two inner edges cross.
    distances = [g.vector('DOT_PRODUCT', g.vector('SUBTRACT', values[b], values[a]), lateral)
                 for a, b in ((0, 1), (2, 3), (0, 2), (1, 3))]
    order = g.all(*(g.compare(d, 1e-5, 'GREATER_THAN') for d in distances))
    checks.extend((g.stat(table, order), g.compare(n, MAX_KNOTS, 'LESS_EQUAL', 'INT')))
    table = bridge._position(g, table, bridge._mix(g, values[1], values[2]))
    events = g.store(events, 'st_bu_gap_residual', gap(query(metric)))
    events = bridge._position(g, events, bridge._mix(g, query(metric)[1], query(metric)[2]))
    valid = g.all(*checks)
    diagnostics = _line(g, 1)
    for key, value, kind in (
            ('valid', valid, 'BOOLEAN'), ('stations', n, 'INT'), ('events', bridge._size(g, events), 'INT'),
            ('common_start', lo, 'FLOAT'), ('common_end', hi, 'FLOAT'),
            ('minimum_gap', g.stat(table, g.named('st_bu_gap', 'FLOAT')), 'FLOAT'),
            ('maximum_gap', g.stat(table, g.named('st_bu_gap', 'FLOAT'), output='Max'), 'FLOAT')):
        diagnostics = g.store(diagnostics, 'st_bu_gap_'+key, value, kind)
    for name, geometry in (('Stations', table), ('Events', events)):
        g.set(g.switch(valid, None, geometry, 'GEOMETRY'), out.inputs[name])
    g.set(diagnostics, out.inputs['Diagnostics']); g.set(valid, out.inputs['Valid'])
    for name, value in (('Origin', origin), ('Axis', axis), ('Lateral', lateral)): g.set(value, out.inputs[name])
    tree['st_construction_only'] = True
    tree['st_independent_terminal_planes'] = True
    return tree
